WITH with_dims AS (SELECT e.*, p.store_name, p.region, p.opened_date FROM inventory e INNER JOIN stores p ON e.store_id = p.id), enriched AS (SELECT a.*, p.stock_qty FROM with_dims a LEFT JOIN products p ON a.product_id = p.id WHERE p.product_name LIKE 'Ru%'), with_windows AS (SELECT id, store_id, quantity, last_restock, opened_date, SUM(quantity) OVER (PARTITION BY product_id ORDER BY quantity ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity, ROW_NUMBER() OVER w_running AS seq_no, SUM(quantity) OVER (PARTITION BY region ORDER BY stock_qty ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity FROM enriched WINDOW w_running AS (PARTITION BY product_id, store_id ORDER BY quantity ASC, id ASC)), deduped AS (SELECT id, store_id, opened_date, cumulative_quantity, running_quantity FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY cumulative_quantity ASC, id ASC) AS dedup_rank FROM with_windows) x WHERE dedup_rank = 1) SELECT id, store_id, opened_date, cumulative_quantity, running_quantity FROM deduped;
